'use client';

import { useEffect, useState } from 'react';
import CreateMeeting from "../components/createMeeting";
import UserProfile from "../Components/UserProfile";
import ConferenceTable from "../Components/ConfereneTable";


interface UserInfo {
  name: string;
  email: string;
  picture: string;
}

interface Meeting {
  title: string;
  startTime: string;
  endTime: string;
  timeZone: string;
  attendees: string[];
}

interface ConferenceRecord {
  id: string;
  name: string;
  startTime: string;
  endTime: string;
  space?: string; // Optional, depending on your data
  expireTime?: string; // Optional, depending on your data
}


interface Transcript {
  transcriptId: string;
  startTime: string;
  endTime: string;
  languageCode: string;
}

interface TranscriptEntry {
  startTime: string;
  endTime: string;
  text: string;
  speaker: {
    email: string;
  };
}

export default function Dashboard() {
  const [authStatus, setAuthStatus] = useState<string | null>(null);
  const [userInfo, setUserInfo] = useState<UserInfo | null>(null);
  const [meetLink, setMeetLink] = useState<string | null>(null);
  const [meetingDetails, setMeetingDetails] = useState<Meeting>({
    title: '',
    startTime: '',
    endTime: '',
    timeZone: 'America/Los_Angeles',
    attendees: [],
  });
  const [conferenceRecords, setConferenceRecords] = useState<ConferenceRecord[]>([]);
  const [transcripts, setTranscripts] = useState<Transcript[]>([]);
  const [transcriptEntries, setTranscriptEntries] = useState<TranscriptEntry[]>([]);
  const [selectedConferenceId, setSelectedConferenceId] = useState<string | null>(null);
  const [selectedTranscriptId, setSelectedTranscriptId] = useState<string | null>(null);

  // Load data from localStorage on component mount
  useEffect(() => {
    const storedUserInfo = localStorage.getItem('userInfo');
    if (storedUserInfo) setUserInfo(JSON.parse(storedUserInfo));

    const storedConferenceRecords = localStorage.getItem('conferenceRecords');
    if (storedConferenceRecords) setConferenceRecords(JSON.parse(storedConferenceRecords));

    const storedTranscripts = localStorage.getItem('transcripts');
    if (storedTranscripts) setTranscripts(JSON.parse(storedTranscripts));

    const storedTranscriptEntries = localStorage.getItem('transcriptEntries');
    if (storedTranscriptEntries) setTranscriptEntries(JSON.parse(storedTranscriptEntries));
  }, []);

  // Save data to localStorage whenever it changes
  useEffect(() => {
    if (userInfo) localStorage.setItem('userInfo', JSON.stringify(userInfo));
  }, [userInfo]);

  useEffect(() => {
    localStorage.setItem('conferenceRecords', JSON.stringify(conferenceRecords));
  }, [conferenceRecords]);

  useEffect(() => {
    localStorage.setItem('transcripts', JSON.stringify(transcripts));
  }, [transcripts]);

  useEffect(() => {
    localStorage.setItem('transcriptEntries', JSON.stringify(transcriptEntries));
  }, [transcriptEntries]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const auth = params.get('auth');

    if (auth === 'success') {
      setAuthStatus('Authentication successful!');
      fetchUserInfo();
    } else if (auth === 'failure') {
      setAuthStatus('Authentication failed. Please try again.');
    }
  }, []);

  // Fetch user profile information
  const fetchUserInfo = async () => {
    try {
      const response = await fetch('http://localhost:5001/api/user-info');
      if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
      const data = await response.json();
      setUserInfo(data);
    } catch (error) {
      console.error('Error fetching user info:', error);
    }
  };

  const fetchConferenceRecords = async () => {
    try {
      const response = await fetch('http://localhost:5001/api/conference-records');
      if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
      const data = await response.json();
      console.log(data);
  
      // Process the data to extract the conference ID from the name field
      const processedRecords = data.conferenceRecords.map((record: ConferenceRecord) => {
        const conferenceId = record.name.split('/').pop(); // Extract the conference ID
        return {
          ...record,
          id: conferenceId,
        };
      });
  
      console.log(processedRecords);
  
      // Set the processed records in the state
      setConferenceRecords(processedRecords);
    } catch (error) {
      console.error('Error fetching conference records:', error);
    }
  };
  
  

  // Fetch transcripts for a specific conference
  const fetchTranscripts = async (conferenceId: string) => {
    try {
      const response = await fetch(
        
        `http://localhost:5001/api/conference-records/${conferenceId}/transcripts`
      );
      if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
      const data = await response.json();
      setTranscripts(data.transcripts);
    } catch (error) {
      console.error('Error fetching transcripts:', error);
    }
  };

  // Fetch transcript entries for a specific transcript
  const fetchTranscriptEntries = async (conferenceId: string, transcriptId: string) => {
    try {
      const response = await fetch(
        `http://localhost:5001/api/conference-records/${conferenceId}/transcripts/${transcriptId}/entries`
      );
      if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
      const data = await response.json();
      setTranscriptEntries(data.entries);
    } catch (error) {
      console.error('Error fetching transcript entries:', error);
    }
  };

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setMeetingDetails((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  // Handle attendee input changes
  const handleAttendeesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { value } = e.target;
    setMeetingDetails((prev) => ({
      ...prev,
      attendees: value.split(',').map((email) => email.trim()),
    }));
  };

  // // Create a Google Meet meeting
  // const createMeeting = async () => {
  //   try {
  //     const response = await fetch('http://localhost:5001/api/create-meeting', {
  //       method: 'POST',
  //       headers: {
  //         'Content-Type': 'application/json',
  //       },
  //       body: JSON.stringify(meetingDetails),
  //     });
  //     if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
  //     const data = await response.json();
  //     setMeetLink(data.meetLink);
  //   } catch (error) {
  //     console.error('Error creating meeting:', error);
  //   }
  // };

  return (
    <main style={{ textAlign: 'center', padding: '2rem' }}>
      <h1>Dashboard</h1>
      {authStatus && <p>{authStatus}</p>}

      {/* {userInfo ? (
        <div>
          <h2>Welcome, {userInfo.name}</h2>
          <p>Email: {userInfo.email}</p>
          <img
            src={userInfo.picture}
            alt="Profile Picture"
            style={{ borderRadius: '50%', marginTop: '1rem' }}
          />
        </div>
      ) : (
        <p>Loading user information...</p>
      )} */}
       <UserProfile userInfo={userInfo} />

    <CreateMeeting />
      
      {/* <div style={{ marginTop: '2rem' }}>
        <h2>Create a Google Meet Meeting</h2>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            createMeeting();
          }}
        >
          <div>
            <label>Title:</label>
            <input
              type="text"
              name="title"
              value={meetingDetails.title}
              onChange={handleInputChange}
              required
            />
          </div>
          <div>
            <label>Start Time:</label>
            <input
              type="datetime-local"
              name="startTime"
              value={meetingDetails.startTime}
              onChange={handleInputChange}
              required
            />
          </div>
          <div>
            <label>End Time:</label>
            <input
              type="datetime-local"
              name="endTime"
              value={meetingDetails.endTime}
              onChange={handleInputChange}
              required
            />
          </div>
          <div>
            <label>Time Zone:</label>
            <select
              name="timeZone"
              value={meetingDetails.timeZone}
              onChange={handleInputChange}
              required
            >
              <option value="America/Los_Angeles">Pacific Time (PT)</option>
              <option value="America/New_York">Eastern Time (ET)</option>
              <option value="UTC">UTC</option>
            </select>
          </div>
          <div>
            <label>Attendees (comma-separated emails):</label>
            <input
              type="text"
              name="attendees"
              value={meetingDetails.attendees.join(', ')}
              onChange={handleAttendeesChange}
              required
            />
          </div>
          <button type="submit">Create Meeting</button>
        </form>

        {meetLink && (
          <div style={{ marginTop: '1rem' }}>
            <h3>Google Meet Link:</h3>
            <a href={meetLink} target="_blank" rel="noopener noreferrer">
              {meetLink}
            </a>
          </div>
        )}
      </div> */}

      {/* Fetch Conference Records */}
      <div style={{ marginTop: '2rem' }}>
        <h2>Conference Records</h2>
        <button onClick={fetchConferenceRecords}>Fetch Conference Records</button>
        <ul>
  {conferenceRecords.map((record: ConferenceRecord) => (
    <li key={record.id}>
      <p>Conference Name: {record.name}</p>
      <p>Conference ID: {record.id}</p>
      <p>Start Time: {record.startTime}</p>
      <p>End Time: {record.endTime}</p>
      <button
        onClick={() => {
          setSelectedConferenceId(record.id);
          fetchTranscripts(record.id);
        }}
      >
        Fetch Transcripts
      </button>
    </li>
  ))}
</ul>
      </div>

      {/* Fetch Transcripts */}
      {selectedConferenceId && (
        <div style={{ marginTop: '2rem' }}>
          <h2>Transcripts</h2>
          <ul>
            {transcripts.map((transcript) => (
              <li key={transcript.transcriptId}>
                <p>Transcript ID: {transcript.transcriptId}</p>
                <p>Start Time: {transcript.startTime}</p>
                <p>End Time: {transcript.endTime}</p>
                <button
                  onClick={() => {
                    setSelectedTranscriptId(transcript.transcriptId);
                    fetchTranscriptEntries("1228a674-035f-4198-b40c-165e3d18f1d1", transcript.transcriptId);
                  }}
                >
                  Fetch Transcript Entries
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Fetch Transcript Entries */}
      {selectedTranscriptId && (
        <div style={{ marginTop: '2rem' }}>
          <h2>Transcript Entries</h2>
          <ul>
            {transcriptEntries.map((entry, index) => (
              <li key={index}>
                <p>Speaker: {entry.speaker.email}</p>
                <p>Text: {entry.text}</p>
                <p>Time: {entry.startTime} - {entry.endTime}</p>
              </li>
            ))}
          </ul>
        </div>
      )}
    </main>
  );
}

